∀ {L : Type u_1} {R : Type u_2} [inst : Fintype L] [inst_1 : Fintype R] [inst_2 : DecidableEq L]
  [inst_3 : DecidableEq R] {G : GraphChoices.Peeling.Graph L R} {B N : ℕ} {d : ℝ}
  (P : GraphChoices.Peeling.PreparedDecomposition G B N d), 0 < N

∀ {L : Type u_1} {R : Type u_2} [inst : Fintype L] [inst_1 : Fintype R] [inst_2 : DecidableEq L]
  [inst_3 : DecidableEq R] {H F : GraphChoices.Peeling.Graph L R} {D : ℕ} {ss : List (ℕ × ℕ)}
  {Ps : List (GraphChoices.Peeling.Graph L R)}, GraphChoices.Peeling.PeelingRun H D ss Ps F → Ps.length = ss.length

∀ {V : Type u_1} {E : Type u_2} [Fintype V] [inst : DecidableEq V] (G : GraphChoices.BaseGraph V E) {T : ℕ}
  (ω : Fin T → E × Bool) {a b : ℕ},
  a ≤ b → b ≤ T → ∀ (v : V), GraphChoices.RandomGreedy.state G ω a v ≤ GraphChoices.RandomGreedy.state G ω b v

{L : Type u_1} →
  {R : Type u_2} →
    [DecidableEq L] → [DecidableEq R] → (G : GraphChoices.Peeling.Graph L R) → GraphChoices.OnlinePolicy { x // x ∈ G }

∀ {V : Type u_1} [Fintype V] (m : ℕ) (e : Fin (m + 1) ≃ V) (color : V → Bool),
  color (e ⟨0, ⋯⟩) = false →
    {i | color (e (GraphChoices.Patterns.childIndex i)) = true}.card = Nat.card { v // color v = true }

∀ {L : Type u_1} {R : Type u_2} [inst : Fintype L] [inst_1 : Fintype R] [inst_2 : DecidableEq L]
  [inst_3 : DecidableEq R] {G : GraphChoices.Peeling.Graph L R} {B N : ℕ} {d : ℝ}
  (P : GraphChoices.Peeling.PreparedDecomposition G B N d), ↑(GraphChoices.Peeling.maxLeftDegree G) ≤ d * Real.log ↑N
